import 'package:ecommerce_c19/features/auth/data/repositories/auth_repo_impl.dart';
import 'package:ecommerce_c19/features/auth/domain/repositories/auth_repo.dart';
import 'package:ecommerce_c19/features/auth/domain/use_cases/signUp_usecase.dart';
import 'package:ecommerce_c19/features/auth/presentation/bloc/auth_bloc.dart';
import 'package:flutter/material.dart';

import 'package:ecommerce_c19/core/theme/app_colors.dart';
import 'package:ecommerce_c19/core/routes/app_routes.dart';
import 'package:ecommerce_c19/core/utils/app_assets.dart';
import 'package:ecommerce_c19/core/utils/validators.dart';
import 'package:ecommerce_c19/features/auth/presentation/widgets/auth_button.dart';
import 'package:ecommerce_c19/features/auth/presentation/widgets/auth_text_field.dart';

class RegisterScreen extends StatefulWidget {
  const RegisterScreen({super.key});

  @override
  State<RegisterScreen> createState() => _RegisterScreenState();
}

class _RegisterScreenState extends State<RegisterScreen> {
  final _formKey = GlobalKey<FormState>();
  final _nameController = TextEditingController();
  final _phoneController = TextEditingController();
  final _emailController = TextEditingController();
  final _passwordController = TextEditingController();

  @override
  void dispose() {
    _nameController.dispose();
    _phoneController.dispose();
    _emailController.dispose();
    _passwordController.dispose();
    super.dispose();
  }

  void _signUp() {
    if (!_formKey.currentState!.validate()) return;
    Navigator.pushNamedAndRemoveUntil(context, AppRoutes.main, (_) => false);
  }

  @override
  Widget build(BuildContext context) {
    return BlocProvider(
      create: (context) => AuthBloc(
        SignUpUseCase(authRepository: AuthRepositoryImpl(
          authRemoteDataSource: AuthRemoteDataSourceImpl(),
        )),
      ),
      child: Container(),
    )(
      child: Scaffold(
        backgroundColor: AppColors.primary,
        body: SafeArea(
          child: SingleChildScrollView(
            padding: const EdgeInsets.fromLTRB(16, 40, 16, 24),
            child: Form(
              key: _formKey,
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Center(child: Image.asset(AppAssets.logo, width: 240)),
                  const SizedBox(height: 40),
                  AuthTextField(
                    label: 'Full Name',
                    hint: 'enter your full name',
                    controller: _nameController,
                    keyboardType: TextInputType.name,
                    validator: Validators.required,
                  ),
                  const SizedBox(height: 28),
                  AuthTextField(
                    label: 'Mobile Number',
                    hint: 'enter your mobile no.',
                    controller: _phoneController,
                    keyboardType: TextInputType.phone,
                    validator: Validators.required,
                  ),
                  const SizedBox(height: 28),
                  AuthTextField(
                    label: 'E-mail address',
                    hint: 'enter your email address',
                    controller: _emailController,
                    keyboardType: TextInputType.emailAddress,
                    validator: Validators.email,
                  ),
                  const SizedBox(height: 28),
                  AuthTextField(
                    label: 'Password',
                    hint: 'enter your password',
                    controller: _passwordController,
                    textInputAction: TextInputAction.done,
                    isPassword: true,
                    validator: Validators.password,
                  ),
                  const SizedBox(height: 56),
                  AuthButton(text: 'Sign up', onPressed: _signUp),
                ],
              ),
            ),
          ),
        ),
      ),
    );
  }
}
